import json
from pathlib import Path
from lesson_authoring import entry as E
N='https://www.nidcd.nih.gov/health/smell-disorders'
W=[
E('osmium','英 /ˈɒzmiəm/；美 /ˈɑːzmiəm/','锇〔化学元素 Os〕','元素名记下了发现时一种相关化合物的强烈气味。','希腊 osme 气味 + 元素名称常见的 -ium，形成近代元素名。命名线索是其氧化物的气味，并不是“金属”这个概念本身。',[['希腊 osme','气味'],['近代元素命名 osmium','因相关氧化物气味而得名的锇']],'锇是一种密度很高的金属。为什么一个金属名字里会藏着“气味”？因为发现和研究过程中，相关的四氧化锇气味很明显。要记住的是命名时注意到的现象，不能据此说所有锇材料都像香水一样散发气味。','the element osmium；an osmium alloy；osmium tetroxide。','osmium 是元素，osmium tetroxide 是它的一种氧化物。名字的由来不等于元素与化合物有完全一样的性质。',('The student located osmium in the periodic table.','学生在元素周期表里找到了锇。'),('The exhibit explains why osmium was named after a Greek word for smell.','展览解释了锇为何以希腊语中表示气味的词来命名。'),sources=['https://periodic-table.rsc.org/element/76/Osmium','https://www.etymonline.com/word/osmium','https://en.wiktionary.org/wiki/osmium']),
E('anosmia','英 /æˈnɒzmiə/；美 /æˈnɑːzmiə/','嗅觉丧失；失嗅','气味在外面，鼻子却辨认不到。','希腊否定成分 an- 无 + osme 气味，经医学名词后缀 -ia 构成。元音前的否定形式为 an-，不要拆成普通英语 an。',[['希腊 an-；osme','无；气味'],['医学名词 anosmia','失去嗅觉的状态']],'最容易记的画面是：别人闻得到咖啡，你却闻不到。它说的是嗅觉能力的丧失，不是食物真的没有气味，也不等于舌头的基本味觉全部消失。因为闻香参与食物风味，失嗅的人也可能觉得食物少了很多味道。','a loss of smell called anosmia；congenital anosmia；people with anosmia。','anosmia 是闻不到；parosmia 是闻到的气味变了；phantosmia 是没有相应气味来源却有嗅觉感受。三者不要统称成一个词。',('The article describes how anosmia can change the experience of eating.','文章描述了失嗅怎样改变吃东西的感受。'),('She wrote about living with anosmia and no longer smelling fresh coffee.','她写了自己失嗅后的生活，以及再也闻不到现煮咖啡香味的感受。'),sources=[N,'https://en.wiktionary.org/wiki/anosmia']),
E('parosmia','英 /pəˈrɒzmiə/；美 /pəˈrɑːzmiə/','嗅觉倒错；气味感知失真','气味确实存在，但闻起来和原来不一样了。','医学组合 para- 偏离、异常 + osme 气味 + -ia 状态。para- 在这里不是平行，也不是普通英语 par。',[['希腊 para-；osme','偏离正常；气味'],['医学名词 parosmia','对实际气味的感知发生失真']],'可以想象：桌上真有一杯咖啡，但原本熟悉的香味却变得难闻。问题不是环境凭空多了一股味道，而是原有气味被感受成了别的样子。用“气味变样了”来记，比背一个生硬的中文术语更直观。','experience parosmia；describe parosmia；changes in smell caused by parosmia。','parosmia 有实际气味刺激，只是感知走样；phantosmia 则没有对应的外部气味刺激。parosmia 也不是单纯闻得较淡。',('With parosmia, a familiar perfume may smell very different.','出现嗅觉倒错时，一款熟悉的香水可能闻起来大不一样。'),('The interview describes one person’s experience of parosmia after an illness.','访谈描述了一个人生病后经历嗅觉倒错的感受。'),sources=[N,'https://en.wiktionary.org/wiki/parosmia']),
E('phantosmia','美 /fænˈtɑːzmiə/','幻嗅','像闻到了味道，但环境中没有相应的气味来源。','phantom 幻影一系的 phant- 与希腊 osme 气味组合，末尾用医学状态名词形式 -ia。phantom 自身可追溯到希腊 phantasma 显现、幻象。',[['phantom 一系；希腊 osme','幻象、并无实物的感受；气味'],['医学名词 phantosmia','没有对应外部气味刺激的嗅觉感受']],'名字可以记成“气味的幻影”。例如，一个人感觉闻到烟味，但周围并没有产生那种气味的来源。这个词描述的是一种嗅觉体验，单靠词名不能判断原因，也不表示当事人在故意编造。','phantom smells；experience phantosmia；episodes of phantosmia。','phantosmia 与 parosmia 的区别是有没有对应的气味刺激。前者像凭空出现一个气味感受，后者像把已有气味认成了别的样子。',('The patient described episodes of phantosmia as a smell of smoke with no source nearby.','那位患者描述，幻嗅发作时像闻到了烟味，附近却没有相应来源。'),('The leaflet explains the difference between phantosmia and distorted smells.','宣传页解释了幻嗅与气味感知失真的区别。'),sources=[N,'https://my.clevelandclinic.org/health/diseases/24799-phantosmia','https://en.wiktionary.org/wiki/phantosmia'])]
ROOT=dict(id='C0925',meaning='气味；闻到的感觉',core='OSM = SMELL',image='先问三件事：闻不闻得到？闻起来变没变？环境中真有那个气味吗？',intro='希腊 osme 表示气味。英语里它一方面进入元素名 osmium，另一方面进入描述嗅觉状态的医学词。这一组不用背很多术语，分清三个常见的嗅觉变化就有实际阅读价值。',forms='osm- / osmo- 表示气味；-osmia 常用于嗅觉状态名称。an- 是否定，para- 在这里表示异常偏离，phant- 连到幻象。它们不是同一种问题的不同叫法。',branches=[['按气味线索命名元素','osmium'],['闻不到','anosmia'],['闻到的味道失真','parosmia'],['没有相应来源却有气味感受','phantosmia']],contrasts='osmium 里的气味是命名依据；三个 -osmia 词讨论人的感知。记词时用具体场景分开，不要把所有嗅觉问题都翻成失嗅。',practice='Anosmia is a loss of smell; parosmia changes how a real smell is perceived; phantosmia involves a smell without a matching source.\n\nanosmia 是闻不到，parosmia 是实际气味闻着变了，phantosmia 是没有相应来源却闻到了气味。',words=[x['word'] for x in W],exclude={w:'较少见的细分嗅觉术语或相关派生形式，本轮先掌握最有辨识价值的四个词。' for w in ['anosmic','cacosmia','coprosmia','dysosmia','dysosmic','euosmia','hyperosmia','hyperosmic','hyposmia','hyposmic','osmolagnia','osmophobia','osphresiolagnia','troposmia']})
if __name__=='__main__':
 for name,data in [('roots_osm',[ROOT]),('words_osm',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
